import { readFile, writeFile } from 'node:fs/promises';
const palette = JSON.parse(
  await readFile(new URL('../src/platform/visual/aether-palette.json', import.meta.url), 'utf8'),
);
await writeFile(
  new URL('../src/app/aether-tokens.css', import.meta.url),
  '/* Generated by scripts/generate-aether-tokens.mjs. Edit aether-palette.json. */\n:root {\n' +
    Object.entries(palette)
      .map(([name, value]) => `  --aether-${name}: ${value};`)
      .join('\n') +
    '\n}\n',
);
